"""Build a self-contained, offline viewer of the derived results."""
from pathlib import Path
import json,pandas as pd
R=Path(__file__).resolve().parents[1];D=R/'data/derived'
a=pd.read_csv(D/'annual.csv').to_dict(orient='records');d=pd.read_csv(D/'decomposition.csv').to_dict(orient='records');h=pd.read_csv(D/'hhi_attribution.csv').to_dict(orient='records')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manganese Recovery Observatory</title><style>
:root{font-family:system-ui,sans-serif;color:#233847;background:#f4f6f5}body{max-width:1100px;margin:40px auto;padding:0 24px}header{border-bottom:3px solid #006d77;padding-bottom:20px}h1{font-size:36px;letter-spacing:-1px;margin:10px 0}h2{font-size:20px}p{max-width:82ch;line-height:1.6}.kicker{color:#006d77;text-transform:uppercase;letter-spacing:2px;font-size:12px;font-weight:700}select{font:inherit;padding:10px;border-radius:6px;background:white;border:1px solid #9baab1}section{margin:24px 0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:white;padding:20px;border:1px solid #dbe2e3;border-radius:8px}.big{font-size:30px;font-weight:650;margin:10px 0}.muted{font-size:13px;color:#576d78}.panel{background:white;border:1px solid #dbe2e3;border-radius:8px;padding:24px;margin-top:20px}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:10px;border-bottom:1px solid #e4e8e9}th:first-child,td:first-child{text-align:left}svg{width:100%;height:auto}a{color:#006d77}footer{padding:25px 0;font-size:13px;color:#576d78}@media(max-width:760px){.cards{grid-template-columns:repeat(2,1fr)}h1{font-size:28px}.panel{padding:14px}th,td{padding:6px;font-size:12px}}
</style><header><div class="kicker">Caucasus · commodity frontiers · reproducible evidence</div><h1>Manganese Recovery Observatory</h1><p>Georgia’s silicomanganese exports, 2015–2025. Compare physical throughput, gross dollar receipts and the distribution of sales across destinations.</p><label for="pair">Comparison </label><select id="pair"></select></header><main><section class="cards" id="cards"></section><section class="panel"><h2>Read the outcomes together</h2><p id="interpretation"></p><p class="muted">Receipts are current USD; weight is the reported export net weight. A lower HHI means lower destination concentration. These measures do not estimate wages, profit, mine output or environmental recovery.</p><div id="chart"></div><p class="muted">Lines: export weight (teal) and receipts (orange), indexed to the selected starting year. Dashed line: 100.</p></section><section class="panel"><h2>What changed within routes?</h2><p>Symmetric midpoint accounting for routes active at both endpoints. Entry and exit are kept separate; no missing-route price is invented.</p><table><thead><tr><th>Component</th><th>Million current USD</th></tr></thead><tbody id="decomposition"></tbody></table></section><section class="panel"><h2>Destination concentration</h2><p id="attribution"></p><p class="muted">The two-group attribution averages both update orders, recalculating totals in each hybrid state. It is an accounting allocation conditional on grouping Türkiye and the United States together; it is not causal.</p></section><section class="panel"><h2>Complete annual series</h2><table><thead><tr><th>Year</th><th>Receipts, $m</th><th>Weight, kt</th><th>USD/kg</th><th>Value HHI</th><th>Destinations</th></tr></thead><tbody id="annual"></tbody></table></section></main><footer>Shivam Gupta · snapshot retrieved 16 October 2026 · source: UN Comtrade · <a href="https://github.com/shi1720/manganese-recovery-observatory">Code, data, paper and limitations</a><br>Runs offline. No network request is needed to calculate or display these results.</footer><script>
const annual=__ANNUAL__,decs=__DECS__,hhis=__HHIS__;
const el=id=>document.getElementById(id),fmt=(n,k=2)=>n.toLocaleString('en-US',{minimumFractionDigits:k,maximumFractionDigits:k}),pct=(b,t,k)=>100*(t[k]/b[k]-1);
const select=el('pair');decs.forEach((r,i)=>{let o=document.createElement('option');o.value=i;o.textContent=r.base+' → '+r.target;select.appendChild(o)});select.value=3;
el('annual').innerHTML=annual.map(r=>`<tr><td>${r.year}</td><td>${fmt(r.value_usd/1e6)}</td><td>${fmt(r.weight_kg/1e6)}</td><td>${fmt(r.unit_usd_kg,3)}</td><td>${fmt(r.hhi_value,3)}</td><td>${r.n_destinations}</td></tr>`).join('');
function update(){const r=decs[+select.value],b=annual.find(x=>x.year===r.base),t=annual.find(x=>x.year===r.target),h=hhis.find(x=>x.base===r.base&&x.target===r.target);
 const metrics=[['Export weight','weight_kg','Physical throughput'],['Export receipts','value_usd','Gross nominal dollar receipts'],['Unit receipts','unit_usd_kg','Composition and within-route changes'],['Value concentration','hhi_value','HHI by destination receipts']];
 el('cards').innerHTML=metrics.map(([l,k,s])=>`<article class="card"><div>${l}</div><div class="big">${pct(b,t,k)>0?'+':''}${fmt(pct(b,t,k))}%</div><div class="muted">${s}</div></article>`).join('');
 const w=pct(b,t,'weight_kg'),v=pct(b,t,'value_usd'),c=pct(b,t,'hhi_value');
 el('interpretation').textContent=`From ${r.base} to ${r.target}, weight ${w>0?'rose':'fell'} by ${fmt(Math.abs(w))}%, gross receipts ${v>0?'rose':'fell'} by ${fmt(Math.abs(v))}%, and value concentration ${c>0?'rose':'fell'} by ${fmt(Math.abs(c))}%. The conclusion depends on both the ledger and the comparison year.`;
 el('decomposition').innerHTML=[['Common routes: weight','quantity_effect_common'],['Common routes: unit receipts','unit_receipts_effect_common'],['Recorded route entry','entry'],['Recorded route exit','exit'],['Total receipts change','delta_value']].map(([l,k])=>`<tr><td>${l}</td><td>${fmt(r[k]/1e6)}</td></tr>`).join('');
 el('attribution').textContent=`Value HHI moved from ${fmt(h.hhi0,4)} to ${fmt(h.hhi1,4)}. The Türkiye–United States group contributes ${fmt(h.us_turkey_effect,5)} HHI points; all remaining destinations contribute ${fmt(h.other_effect,5)}. Effective destinations moved from ${fmt(1/h.hhi0)} to ${fmt(1/h.hhi1)}.`;
 const vals=annual.flatMap(x=>[x.weight_kg/b.weight_kg*100,x.value_usd/b.value_usd*100]),max=Math.ceil(Math.max(...vals)/50)*50;
 const X=y=>55+(y-2015)*85,Y=v=>250-v/max*215;let svg=`<svg role="img" aria-label="Annual export weight and receipts indexed to the selected starting year" viewBox="0 0 950 300"><line x1="55" y1="${Y(100)}" x2="905" y2="${Y(100)}" stroke="#aaa" stroke-dasharray="5 4"/>`;
 for(let z=0;z<=max;z+=50)svg+=`<text x="45" y="${Y(z)+4}" text-anchor="end" font-size="12">${z}</text>`;
 for(const [k,color] of [['weight_kg','#006d77'],['value_usd','#d17a22']]){svg+=`<polyline fill="none" stroke="${color}" stroke-width="3" points="${annual.map(x=>X(x.year)+','+Y(x[k]/b[k]*100)).join(' ')}"/>`;for(const x of annual)svg+=`<circle cx="${X(x.year)}" cy="${Y(x[k]/b[k]*100)}" r="3" fill="${color}"/>`}
 for(let y=2015;y<=2025;y++)svg+=`<text x="${X(y)}" y="280" text-anchor="middle" font-size="12">${y}</text>`;el('chart').innerHTML=svg+'</svg>';
}select.addEventListener('change',update);update();
</script></html>'''
html=html.replace('__ANNUAL__',json.dumps(a)).replace('__DECS__',json.dumps(d)).replace('__HHIS__',json.dumps(h));(R/'observatory.html').write_text(html)
print('Built observatory.html')
